import "dotenv/config";
import { db } from "@/app/lib/db";
import { eq } from "drizzle-orm";
import {
  artists,
  roles,
  passwords,
  artistsArtworks,
  comments,
  likes,
  follows,
  rooms,
  rolesPermissions,
  permissions,
  artworks,
} from "./schema";

async function main() {
  console.log("🌱 Seeding database...");

  // 1. CLEANUP
  await db.delete(likes);
  await db.delete(comments);
  await db.delete(follows);
  await db.delete(artistsArtworks);
  await db.delete(artworks);
  await db.delete(passwords);
  await db.delete(artists);
  await db.delete(rooms);
  await db.delete(rolesPermissions);
  await db.delete(roles);
  await db.delete(permissions);

  console.log("✅ Cleaned up existing data");

  // --- PERMISSIONS ---
  const insertedPermissions = await db
    .insert(permissions)
    .values([
      { action: "create", entity: "artwork", access: "own" },
      { action: "read", entity: "artwork", access: "any" },
      { action: "update", entity: "artwork", access: "own" },
      { action: "delete", entity: "artwork", access: "own" },
      { action: "delete", entity: "artwork", access: "any" },
      { action: "create", entity: "comment", access: "own" },
      { action: "delete", entity: "comment", access: "own" },
      { action: "delete", entity: "comment", access: "any" },
      { action: "manage", entity: "user", access: "any" },
    ])
    .returning();

  console.log(`✅ Created ${insertedPermissions.length} permissions`);

  // --- ROLES & ROLE PERMISSIONS ---
  const [userRole] = await db
    .insert(roles)
    .values({ name: "user" })
    .returning();
  const [adminRole] = await db
    .insert(roles)
    .values({ name: "admin" })
    .returning();

  const userPerms = insertedPermissions.filter((p) =>
    [
      "create:artwork:own",
      "read:artwork:any",
      "update:artwork:own",
      "delete:artwork:own",
      "create:comment:own",
      "delete:comment:own",
    ].includes(`${p.action}:${p.entity}:${p.access}`),
  );

  await db
    .insert(rolesPermissions)
    .values(
      userPerms.map((p) => ({ roleId: userRole.id, permissionId: p.id })),
    );

  await db.insert(rolesPermissions).values(
    insertedPermissions.map((p) => ({
      roleId: adminRole.id,
      permissionId: p.id,
    })),
  );

  console.log("✅ Created roles: user, admin");

  // --- ARTISTS & PASSWORDS ---
  const hashedPassword =
    "$2a$10$BQToDNdBtBKCvnrTmMi5m.NK.7i6Qx7YASs.jTkE86I5zqxzE8klC";

  const insertedArtists = await db
    .insert(artists)
    .values([
      {
        username: "alice_draws",
        email: "alice@example.com",
        avatar: "https://api.dicebear.com/7.x/adventurer/svg?seed=alice",
        roleId: userRole.id,
      },
      {
        username: "bob_artist",
        email: "bob@example.com",
        avatar: "https://api.dicebear.com/7.x/adventurer/svg?seed=bob",
        roleId: userRole.id,
      },
      {
        username: "charlie_creative",
        email: "charlie@example.com",
        avatar: "https://api.dicebear.com/7.x/adventurer/svg?seed=charlie",
        roleId: userRole.id,
      },
      {
        username: "netrunners",
        email: "admin@drawgether.com",
        emailVerified: new Date(),
        avatar: "https://i.imgur.com/tu2cpU0.png",
        roleId: adminRole.id,
      },
      {
        username: "diana_palette",
        email: "diana@example.com",
        avatar: "https://api.dicebear.com/7.x/adventurer/svg?seed=diana",
        roleId: userRole.id,
      },
      {
        username: "eric_canvas",
        email: "eric@example.com",
        avatar: "https://api.dicebear.com/7.x/adventurer/svg?seed=eric",
        roleId: userRole.id,
      },
    ])
    .returning();

  const [alice, bob, charlie, netrunners, diana, eric] = insertedArtists;

  await db.insert(passwords).values(
    insertedArtists.map((artist) => ({
      artistId: artist.id,
      hash: hashedPassword,
    })),
  );

  console.log(`✅ Created ${insertedArtists.length} artists`);

  // --- ARTWORKS & ARTIST-ARTWORK RELATIONS ---
  const artworkTemplates = [
    {
      theme: "Mechanical space spiders",
      artworkImage:
        "data:image/png;base64,",
    },
    {
      theme: "Celestial lighthouse",
      artworkImage:
        "data:image/png;base64,",
    },
    {
      theme: "Candyland in space",
      artworkImage:
        "data:image/png;base64,",
    },
    {
      theme: "Steampunk space exploration",
      artworkImage:
        "data:image/png;base64,",
    },
    {
      theme: "Lost in the labyrinth",
      artworkImage:
        "data:image/png;base64,",
    },
    {
      theme: "Robot revolution",
      artworkImage:
        "data:image/png;base64,",
    },
    {
      theme: "Crystal clear lake",
      artworkImage:
        "data:image/png;base64,",
    },
    {
      theme: "Enchanted clockwork carousel",
      artworkImage:
        "data:image/png;base64,",
    },
    {
      theme: "Floating dragon island",
      artworkImage:
        "data:image/png;base64,",
    },
    {
      theme: "Quantum pirate ship",
      artworkImage:
        "data:image/png;base64,",
    },
    {
      theme: "Giant insects",
      artworkImage:
        "data:image/png;base64,",
    },
    {
      theme: "Ancient space pyramid",
      artworkImage:
        "data:image/png;base64,",
    },
    {
      theme: "Enchanted clockwork carousel",
      artworkImage:
        "data:image/png;base64,",
    },
    {
      theme: "Carnival in the clouds",
      artworkImage:
        "data:image/png;base64,",
    },
    {
      theme: "Steampunk space exploration",
      artworkImage:
        "data:image/png;base64,",
    },
    {
      theme: "Neon-lit space aquarium",
      artworkImage:
        "data:image/png;base64,",
    },
    {
      theme: "Ancient star map",
      artworkImage:
        "data:image/png;base64,",
    },
    {
      theme: "Mechanical butterfly migration",
      artworkImage:
        "data:image/png;base64,",
    },
    {
      theme: "Ice kingdom",
      artworkImage:
        "data:image/png;base64,",
    },
    {
      theme: "Floating crystal castle",
      artworkImage:
        "data:image/png;base64,",
    },
    {
      theme: "Mythical sea monsters",
      artworkImage:
        "data:image/png;base64,",
    },
  ];

  const artworkRows = artworkTemplates.map((artwork, index) => ({
    ...artwork,
    createdAt: new Date(
      Date.now() -
        (artworkTemplates.length - index) * 6 * 60 * 60 * 1000 -
        (index % 5) * 17 * 60 * 1000,
    ),
  }));

  const insertedArtworks = await db
    .insert(artworks)
    .values(artworkRows)
    .returning();

  const collaborationPool = [alice, bob, charlie, diana, eric];
  const artistArtworkRows = insertedArtworks
    .map((artwork, index) => {
      const desiredCount = 2 + (index % 4);
      const start = index % collaborationPool.length;
      const rotatedArtists = [
        ...collaborationPool.slice(start),
        ...collaborationPool.slice(0, start),
      ];

      return rotatedArtists
        .slice(0, desiredCount)
        .map((artist) => ({ artistId: artist.id, artworkId: artwork.id }));
    })
    .flat();

  await db.insert(artistsArtworks).values(artistArtworkRows);

  const artworksCountByArtist = new Map<string, number>();
  for (const row of artistArtworkRows) {
    artworksCountByArtist.set(
      row.artistId,
      (artworksCountByArtist.get(row.artistId) ?? 0) + 1,
    );
  }

  console.log(`✅ Created ${insertedArtworks.length} artworks`);

  // --- COMMENTS ---
  const commentersPool = [alice, bob, charlie, diana, eric, netrunners];
  const commentTemplates = [
    "Love the colors in this one!",
    "This is amazing work!",
    "Such a creative concept!",
    "Beautiful piece.",
    "The details are incredible.",
    "This composition works so well.",
    "I keep coming back to this one.",
  ];

  const commentRows = insertedArtworks
    .map((artwork, index) => {
      const commentsForArtwork = 1 + (index % 3);
      const start = (index * 2) % commentersPool.length;
      const rotatedCommenters = [
        ...commentersPool.slice(start),
        ...commentersPool.slice(0, start),
      ];

      return Array.from({ length: commentsForArtwork }, (_, offset) => ({
        content: commentTemplates[(index + offset) % commentTemplates.length],
        artistId: rotatedCommenters[offset].id,
        artworkId: artwork.id,
        createdAt: new Date(
          artwork.createdAt.getTime() +
            (offset + 1) * 19 * 60 * 1000 +
            (index % 4) * 7 * 60 * 1000,
        ),
      }));
    })
    .flat();

  const insertedComments = await db
    .insert(comments)
    .values(commentRows)
    .returning();

  const commentsCountByArtwork = new Map<string, number>();
  for (const row of commentRows) {
    commentsCountByArtwork.set(
      row.artworkId,
      (commentsCountByArtwork.get(row.artworkId) ?? 0) + 1,
    );
  }

  for (const artwork of insertedArtworks) {
    await db
      .update(artworks)
      .set({ commentsCount: commentsCountByArtwork.get(artwork.id) ?? 0 })
      .where(eq(artworks.id, artwork.id));
  }

  console.log(`✅ Created ${insertedComments.length} comments`);

  // --- LIKES ---
  const likersPool = [alice, bob, charlie, diana, eric, netrunners];
  const likeRows = insertedArtworks
    .map((artwork, index) => {
      const likesForArtwork = 2 + (index % 4);
      const start = (index * 3) % likersPool.length;
      const rotatedLikers = [
        ...likersPool.slice(start),
        ...likersPool.slice(0, start),
      ];

      return rotatedLikers.slice(0, likesForArtwork).map((artist, offset) => ({
        artistId: artist.id,
        artworkId: artwork.id,
        createdAt: new Date(
          artwork.createdAt.getTime() +
            45 * 60 * 1000 +
            offset * 11 * 60 * 1000,
        ),
      }));
    })
    .flat();

  const insertedLikes = await db.insert(likes).values(likeRows).returning();

  const likesCountByArtwork = new Map<string, number>();
  for (const row of likeRows) {
    likesCountByArtwork.set(
      row.artworkId,
      (likesCountByArtwork.get(row.artworkId) ?? 0) + 1,
    );
  }

  for (const artwork of insertedArtworks) {
    await db
      .update(artworks)
      .set({ likesCount: likesCountByArtwork.get(artwork.id) ?? 0 })
      .where(eq(artworks.id, artwork.id));
  }

  console.log(`✅ Created ${insertedLikes.length} likes`);

  // --- FOLLOWS ---
  const insertedFollows = await db
    .insert(follows)
    .values([
      { followerId: bob.id, followingId: alice.id },
      { followerId: charlie.id, followingId: alice.id },
      { followerId: alice.id, followingId: bob.id },
      { followerId: charlie.id, followingId: bob.id },
      { followerId: alice.id, followingId: charlie.id },
    ])
    .returning();

  await db
    .update(artists)
    .set({
      followerCount: 2,
      followingCount: 2,
      artworksCount: artworksCountByArtist.get(alice.id) ?? 0,
    })
    .where(eq(artists.id, alice.id));
  await db
    .update(artists)
    .set({
      followerCount: 2,
      followingCount: 1,
      artworksCount: artworksCountByArtist.get(bob.id) ?? 0,
    })
    .where(eq(artists.id, bob.id));
  await db
    .update(artists)
    .set({
      followerCount: 1,
      followingCount: 2,
      artworksCount: artworksCountByArtist.get(charlie.id) ?? 0,
    })
    .where(eq(artists.id, charlie.id));

  console.log(`✅ Created ${insertedFollows.length} follow relationships`);

  console.log("🎉 Seeding completed successfully!");
}

main()
  .catch((e) => {
    console.error("❌ Seeding failed:", e);
    process.exit(1);
  })
  .finally(() => {
    process.exit(0);
  });
